(function(){try{
if(window.__spYtAdskip)return;window.__spYtAdskip=1;
var mutedByUs=false,wasMuted=false;
function findVideo(){return document.querySelector('video.html5-main-video')||document.querySelector('video');}
function tick(){
  try{
    var skip=document.querySelector('.ytp-skip-ad-button,.ytp-ad-skip-button,.ytp-skip-ad-button-modern,.ytp-ad-skip-button-container button');
    if(skip){skip.click();}
    var player=document.querySelector('.html5-video-player');
    var v=findVideo();
    if(player&&v){
      if(player.classList.contains('ad-showing')||player.classList.contains('ad-interrupting')){
        if(!mutedByUs){wasMuted=v.muted;try{v.muted=true;}catch(e){}mutedByUs=true;}
        try{v.playbackRate=16;}catch(e){}
        if(v.duration&&isFinite(v.duration)&&v.currentTime<v.duration-0.25){try{v.currentTime=v.duration-0.2;}catch(e){}}
      }else if(mutedByUs){
        try{v.muted=wasMuted;}catch(e){}
        mutedByUs=false;
        try{if(v.playbackRate>2)v.playbackRate=1;}catch(e){}
      }
    }
    var ov=document.querySelector('.ytp-ad-overlay-close-button');
    if(ov)ov.click();
    var dlg=document.querySelector('yt-confirm-dialog-renderer');
    if(dlg){var b=dlg.querySelector('#confirm-button');if(b)b.click();}
  }catch(e){}
}
setInterval(tick,400);
}catch(e){}})();

(function(){try{
if(window.__spShortsHider)return;window.__spShortsHider=1;
function fix(){
  try{
    var m=location.pathname.match(/^\/shorts\/([\w-]{6,})/);
    if(m){location.replace('/watch?v='+m[1]);return;}
    var as=document.querySelectorAll('a[href^="/shorts/"]');
    for(var i=0;i<as.length;i++){
      var mm=(as[i].getAttribute('href')||'').match(/^\/shorts\/([\w-]{6,})/);
      if(mm)as[i].setAttribute('href','/watch?v='+mm[1]);
    }
  }catch(e){}
}
fix();
setInterval(fix,1500);
}catch(e){}})();

(function(){try{
if(window.__spBgPlay)return;window.__spBgPlay=1;
function setup(){
  try{
    if(!('mediaSession' in navigator))return;
    var v=document.querySelector('video,audio');
    if(v){try{navigator.mediaSession.playbackState=v.paused?'paused':'playing';}catch(e){}}
    if(window.MediaMetadata&&!navigator.mediaSession.metadata){
      try{navigator.mediaSession.metadata=new MediaMetadata({title:(document.title||'SP Web App'),artist:location.hostname});}catch(e){}
    }
  }catch(e){}
}
setup();
setInterval(setup,3000);
}catch(e){}})();

(function(){try{
if(window.__spVidDl)return;window.__spVidDl=1;
function toast(msg){
  var t=document.getElementById('__sp_dl_toast');
  if(!t){t=document.createElement('div');t.id='__sp_dl_toast';t.style.cssText='position:fixed;left:50%;bottom:150px;transform:translateX(-50%);background:rgba(0,0,0,.88);color:#fff;padding:10px 16px;border-radius:20px;font-size:14px;z-index:2147483647;max-width:86%;text-align:center;font-family:sans-serif;';if(document.body)document.body.appendChild(t);}
  if(!t)return;
  t.textContent=msg;t.style.display='block';
  clearTimeout(t.__h);t.__h=setTimeout(function(){t.style.display='none';},2600);
}
function bestVideo(){
  var vs=document.querySelectorAll('video'),best=null,area=-1;
  for(var i=0;i<vs.length;i++){var a=(vs[i].offsetWidth||0)*(vs[i].offsetHeight||0);if(a>=area){area=a;best=vs[i];}}
  return best;
}
var btn=document.createElement('div');
btn.textContent='⬇️';
btn.setAttribute('style','position:fixed;right:14px;bottom:76px;width:46px;height:46px;line-height:46px;text-align:center;font-size:22px;background:rgba(233,30,99,.93);border-radius:50%;z-index:2147483646;box-shadow:0 2px 8px rgba(0,0,0,.4);cursor:pointer;');
btn.addEventListener('click',function(){
  var v=bestVideo();
  var src=v?(v.currentSrc||v.src||''):'';
  if(!src){toast('Video nahi mila — pehle video chalao');return;}
  if(src.indexOf('http')===0){
    var a=document.createElement('a');a.href=src;a.setAttribute('download','');document.body.appendChild(a);a.click();a.remove();
    toast('Download shuru ho raha hai…');
  }else{
    toast('इस site पर direct download possible नहीं है (streaming video)');
  }
});
function mount(){if(document.body&&!btn.isConnected)document.body.appendChild(btn);}
mount();
setInterval(mount,2000);
}catch(e){}})();

