(function(){try{
if(window.__spSpeedCtl)return;window.__spSpeedCtl=1;
var rates=[0.5,0.75,1,1.25,1.5,2,3],idx=2;
var chip=document.createElement('div');
chip.setAttribute('style','position:fixed;right:14px;bottom:132px;padding:8px 13px;background:rgba(0,0,0,.8);color:#fff;border-radius:18px;font-size:14px;z-index:2147483646;cursor:pointer;user-select:none;font-family:sans-serif;');
function label(){chip.textContent='⏩ '+rates[idx]+'x';}
function apply(){var vs=document.querySelectorAll('video,audio');for(var i=0;i<vs.length;i++){try{vs[i].playbackRate=rates[idx];}catch(e){}}}
chip.addEventListener('click',function(){idx=(idx+1)%rates.length;label();apply();});
function mount(){if(document.body&&!chip.isConnected)document.body.appendChild(chip);}
mount();label();
setInterval(function(){mount();apply();},2500);
}catch(e){}})();

(function(){try{
if(window.__spPopupBlock)return;window.__spPopupBlock=1;
var lastTap=0;
function mark(){lastTap=Date.now();}
document.addEventListener('pointerdown',mark,true);
document.addEventListener('touchstart',mark,true);
document.addEventListener('click',mark,true);
var origOpen=window.open;
window.open=function(){
  if(Date.now()-lastTap<500){return origOpen.apply(window,arguments);}
  return null;
};
try{
  var origAdd=EventTarget.prototype.addEventListener;
  EventTarget.prototype.addEventListener=function(type,fn,opts){
    if(type==='beforeunload')return;
    return origAdd.call(this,type,fn,opts);
  };
}catch(e){}
}catch(e){}})();

