(function(){try{
if(window.__spDimmer)return;window.__spDimmer=1;
var levels=[0,0.2,0.35,0.5,0.65],idx=2;
var ov=document.createElement('div');
ov.setAttribute('style','position:fixed;left:0;top:0;right:0;bottom:0;background:#000;pointer-events:none;z-index:2147483000;');
function apply(){ov.style.opacity=String(levels[idx]);}
var btn=document.createElement('div');
btn.textContent='🌗';
btn.setAttribute('style','position:fixed;left:14px;bottom:132px;width:46px;height:46px;line-height:46px;text-align:center;font-size:21px;background:rgba(0,0,0,.78);border-radius:50%;z-index:2147483646;cursor:pointer;');
btn.addEventListener('click',function(){idx=(idx+1)%levels.length;apply();});
function mount(){if(document.body){if(!ov.isConnected)document.body.appendChild(ov);if(!btn.isConnected)document.body.appendChild(btn);}apply();}
mount();apply();
setInterval(mount,2500);
}catch(e){}})();

(function(){try{
if(window.__spSleep)return;window.__spSleep=1;
var opts=[0,15,30,45,60],idx=0,timer=null;
function toast(msg){
  var t=document.getElementById('__sp_sleep_toast');
  if(!t){t=document.createElement('div');t.id='__sp_sleep_toast';t.style.cssText='position:fixed;left:50%;bottom:150px;transform:translateX(-50%);background:rgba(0,0,0,.88);color:#fff;padding:10px 16px;border-radius:20px;font-size:14px;z-index:2147483647;max-width:86%;text-align:center;font-family:sans-serif;';if(document.body)document.body.appendChild(t);}
  if(!t)return;
  t.textContent=msg;t.style.display='block';
  clearTimeout(t.__h);t.__h=setTimeout(function(){t.style.display='none';},2800);
}
var btn=document.createElement('div');
btn.setAttribute('style','position:fixed;right:14px;bottom:188px;padding:8px 13px;background:rgba(0,0,0,.8);color:#fff;border-radius:18px;font-size:14px;z-index:2147483646;cursor:pointer;user-select:none;font-family:sans-serif;');
function label(){btn.textContent=opts[idx]===0?'💤 OFF':'💤 '+opts[idx]+'m';}
btn.addEventListener('click',function(){
  idx=(idx+1)%opts.length;label();
  if(timer){clearTimeout(timer);timer=null;}
  if(opts[idx]>0){
    toast('💤 '+opts[idx]+' minute baad media ruk jayega');
    timer=setTimeout(function(){
      var ms=document.querySelectorAll('video,audio');
      for(var i=0;i<ms.length;i++){try{ms[i].pause();}catch(e){}}
      toast('💤 Sleep Timer — media rok diya gaya');
      idx=0;label();timer=null;
    },opts[idx]*60*1000);
  }
});
function mount(){if(document.body&&!btn.isConnected)document.body.appendChild(btn);}
mount();label();
setInterval(mount,2000);
}catch(e){}})();
